  VALUES (v_cid, 'Solomon Times', 'https://www.solomontimes.com/', 'active', 'en', 'solomontimes.com', 'ONLINE_NEWS', 'solomon-times', 'organisation', 'Solomon Islands online news site.')
  RETURNING id INTO v_pid;
  INSERT INTO feeds (publisher_id, feed_url, feed_type, parser_config) VALUES (v_pid, 'https://www.solomontimes.com/rss/latest-news.xml', 'rss', '{}'::jsonb);
  UPDATE publisher_submissions SET publisher_id = v_pid WHERE id = v_sid;
  INSERT INTO editorial_profiles (publisher_id, ownership_type, owner, classification_tags, political_party_association,
    historical_context, current_context, confidence, evidence_summary, evidence_sources,
    classification_date, last_reviewed, evidence_date, review_required)
  VALUES (v_pid, 'Presse en ligne privée', 'Non vérifié', ARRAY['commercial_generalist']::text[], NULL,
    'Site d''information des Îles Salomon.', 'Actualité des Îles Salomon, en anglais.', 'low', 'Propriétaire non vérifié pour ce profil.', '[{"url": "https://www.solomontimes.com/", "note": "Site officiel : Solomon Times", "category": "self_description", "accessed_at": "2026-11-05"}]'::jsonb,
    '2026-11-05', '2026-11-05', '2026-11-05', true);
  RAISE NOTICE '% added: publisher %', 'Solomon Times', v_pid;
END $do$;
SELECT p.id, p.slug, c.iso_code, p.language, f.id AS feed_id FROM publishers p JOIN countries c ON c.id = p.country_id
  JOIN feeds f ON f.publisher_id = p.id WHERE p.slug IN ('san-pedro-sun','7-news-belize','inews-guyana','starnieuws','suriname-herald','radio-ozodi','radio-azatlyk','rfa-burmese','global-new-light-of-myanmar','nova-makedonija','solomon-times') ORDER BY p.id;
SELECT p.slug, e.classification_tags, left(e.historical_context, 60) FROM editorial_profiles e JOIN publishers p ON p.id = e.publisher_id
  WHERE p.slug IN ('san-pedro-sun', '7-news-belize', 'inews-guyana', 'starnieuws', 'suriname-herald', 'radio-ozodi', 'radio-azatlyk', 'rfa-burmese', 'global-new-light-of-myanmar', 'nova-makedonija', 'solomon-times') ORDER BY 1;
ROLLBACK;
